/**
 * ╔══════════════════════════════════════════════════════════════╗
 * ║  ОВА Е ГЛАВНОТО КОПЧЕ ЗА БАЛАНС НА ИГРАТА.                   ║
 * ║  Слободно замени го телото — потписот останува ист.          ║
 * ╚══════════════════════════════════════════════════════════════╝
 *
 * Враќа квалитет 0–100, кој потоа станува оценка (Врвен → Слаб)
 * и директно ја множи продажната цена.
 *
 * @param {number} prosekZdravje    0–100, просечно здравје низ целиот живот
 * @param {number} tochnostSushenje 0–1,  1.0 = совршено погоден прозорец за сушење
 * @param {number} genetika         0–1,  вродениот потенцијал на сортата
 * @param {number} lampaBonus       0–14, бонус од ламбата
 * @param {number} deoviSoStetnik   цели денови поминати со нетретиран штетник
 * @returns {number} квалитет 0–100
 *
 * TODO(ти):  Ова е компромис меѓу ДВЕ различни игри и одлуката е твоја:
 *
 *   А) „Наградувај трпение" — дај му голема тежина на `tochnostSushenje`
 *      и остра казна за `deoviSoStetnik`. Играчот што внимава на секое
 *      растение заработува многукратно повеќе од оној што сади масовно.
 *
 *   Б) „Наградувај обем" — дај му поголема тежина на `genetika` и
 *      `lampaBonus`, а помала на грижата. Тогаш вистинската стратегија
 *      е да купуваш подобри семки и повеќе леи, а не да кликаш.
 *
 * Долунаведената имплементација е намерно во средина (грижата носи
 * најмногу, но генетиката поставува таван), за играта да е играбилна
 * веднаш. Замени ја кога ќе решиш во која насока ја сакаш играта.
 */
function presmetajKvalitet(prosekZdravje, tochnostSushenje, genetika, lampaBonus, deoviSoStetnik){
  const zdrav = stegni(prosekZdravje, 0, 100) / 100;
  const suvo  = stegni(tochnostSushenje, 0, 1);
  const gen   = stegni(genetika, 0, 1);

  // Грижата е основата (0–60), сушењето ја модулира.
  const osnova = 60 * Math.pow(zdrav, 1.1) * (0.55 + 0.45 * suvo);
  // Генетиката поставува таван кон кој се стреми резултатот (0–30).
  const taban  = 30 * gen;
  // Опремата е мал, но сигурен додаток.
  const oprema = stegni(lampaBonus, 0, 14);
  // Секој ден со штетник боли трајно.
  const kazna  = Math.max(0, deoviSoStetnik) * 2.5;

  return stegni(osnova + taban + oprema - kazna, 0, 100);
}

/** Претвора поминати денови сушење во точност 0–1 (види §5 од спецификацијата). */
function tochnostOdSushenje(denovi, imaSushara){
  const d1 = imaSushara ? 8 : 9;      // прв идеален ден
  const d2 = imaSushara ? 14 : 12;    // последен идеален ден
  if (denovi <  d1)     return 0.55;  // предвреме
  if (denovi <= d2)     return 1.00;  // идеално
  if (denovi <= d2 + 4) return 0.80;  // прифатливо
  return 0.65;                        // пресушено
}

/** ТХЦ процент, изведен од квалитетот и генетиката. */
function presmetajTHC(kvalitet, genetika){
  return +(8 + 22 * genetika * (stegni(kvalitet, 0, 100) / 100)).toFixed(1);
}

